package com.marinainsaurralde.plango.ui;
import android.graphics.*;import com.google.android.gms.maps.model.*;import com.marinainsaurralde.plango.data.AgrupadorEventos;import java.util.*;
public final class MarkerIconFactory {private final Map<String,BitmapDescriptor>cache=new HashMap<>();public BitmapDescriptor single(AgrupadorEventos.Categoria c){String key="s"+c;return cache.computeIfAbsent(key,k->draw(symbol(c),Color.rgb(100,204,197)));}public BitmapDescriptor group(int count){String text=count>99?"99+":String.valueOf(count);return cache.computeIfAbsent("g"+text,k->draw(text,Color.rgb(23,107,135)));}private BitmapDescriptor draw(String text,int color){int size=96;Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(color);canvas.drawCircle(size/2f,size/2f-8,size*.38f,p);Path tail=new Path();tail.moveTo(size*.38f,size*.72f);tail.lineTo(size*.5f,size*.98f);tail.lineTo(size*.62f,size*.72f);tail.close();canvas.drawPath(tail,p);p.setColor(Color.WHITE);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(text.length()>2?28:38);Paint.FontMetrics fm=p.getFontMetrics();canvas.drawText(text,size/2f,size/2f-8-(fm.ascent+fm.descent)/2,p);return BitmapDescriptorFactory.fromBitmap(b);}private String symbol(AgrupadorEventos.Categoria c){switch(c){case TEATRO:return "T";case MUSICA:return "♫";case CINE:return "▶";case EXPOSICIONES:return "▣";default:return "•";}}}
